/* Adapted from Gradient Orb by UI Capsule and Glowing Effect by Manu Arora,
retrieved through 21st.dev. See THIRD-PARTY.md for source links and changes. */
(()=>{
const reduce=matchMedia('(prefers-reduced-motion: reduce)');
const canvas=document.querySelector('#orb');
const vertex='attribute vec2 position; varying vec2 vUv; void main(){vUv=position*.5+.5;gl_Position=vec4(position,0.,1.);}';
const fragment="\n  precision highp float;\n\n  uniform float iTime;\n  uniform vec3 iResolution;\n  uniform float hue;\n  uniform float rot;\n  uniform float noiseScale;\n  uniform float innerRadius;\n\n  varying vec2 vUv;\n\n  // --- YIQ color space hue rotation ---\n\n  vec3 rgb2yiq(vec3 c) {\n    return vec3(\n      dot(c, vec3(0.299, 0.587, 0.114)),\n      dot(c, vec3(0.596, -0.274, -0.322)),\n      dot(c, vec3(0.211, -0.523, 0.312))\n    );\n  }\n\n  vec3 yiq2rgb(vec3 c) {\n    return vec3(\n      c.x + 0.956 * c.y + 0.621 * c.z,\n      c.x - 0.272 * c.y - 0.647 * c.z,\n      c.x - 1.106 * c.y + 1.703 * c.z\n    );\n  }\n\n  vec3 adjustHue(vec3 color, float hueDeg) {\n    float hueRad = radians(hueDeg);\n    vec3 yiq = rgb2yiq(color);\n    float cosA = cos(hueRad);\n    float sinA = sin(hueRad);\n    yiq.yz = vec2(yiq.y * cosA - yiq.z * sinA, yiq.y * sinA + yiq.z * cosA);\n    return yiq2rgb(yiq);\n  }\n\n  // --- 3D simplex noise (hash-based) ---\n\n  vec3 hash33(vec3 p3) {\n    p3 = fract(p3 * vec3(0.1031, 0.11369, 0.13787));\n    p3 += dot(p3, p3.yxz + 19.19);\n    return -1.0 + 2.0 * fract(vec3(p3.x + p3.y, p3.x + p3.z, p3.y + p3.z) * p3.zyx);\n  }\n\n  float snoise3(vec3 p) {\n    const float K1 = 0.333333333;\n    const float K2 = 0.166666667;\n    vec3 i = floor(p + (p.x + p.y + p.z) * K1);\n    vec3 d0 = p - (i - (i.x + i.y + i.z) * K2);\n    vec3 e = step(vec3(0.0), d0 - d0.yzx);\n    vec3 i1 = e * (1.0 - e.zxy);\n    vec3 i2 = 1.0 - e.zxy * (1.0 - e);\n    vec3 d1 = d0 - (i1 - K2);\n    vec3 d2 = d0 - (i2 - K1);\n    vec3 d3 = d0 - 0.5;\n    vec4 h = max(0.6 - vec4(dot(d0, d0), dot(d1, d1), dot(d2, d2), dot(d3, d3)), 0.0);\n    vec4 n = h * h * h * h * vec4(\n      dot(d0, hash33(i)),\n      dot(d1, hash33(i + i1)),\n      dot(d2, hash33(i + i2)),\n      dot(d3, hash33(i + 1.0))\n    );\n    return dot(vec4(31.316), n);\n  }\n\n  // --- Orb rendering ---\n\n  vec4 extractAlpha(vec3 colorIn) {\n    float a = max(max(colorIn.r, colorIn.g), colorIn.b);\n    return vec4(colorIn.rgb / (a + 1e-5), a);\n  }\n\n  const vec3 baseColor0 = vec3(0.14, 0.40, 1.0);   // blue\n  const vec3 baseColor1 = vec3(0.10, 0.28, 0.85);     // purple\n  const vec3 baseColor2 = vec3(0.55, 0.85, 1.0);   // orange\n  const vec3 baseColor3 = vec3(0.0, 0.0, 0.0);       // black\n\n  float light1(float intensity, float attenuation, float dist) {\n    return intensity / (1.0 + dist * attenuation);\n  }\n\n  float light2(float intensity, float attenuation, float dist) {\n    return intensity / (1.0 + dist * dist * attenuation);\n  }\n\n  vec4 draw(vec2 uv) {\n    vec3 color0 = adjustHue(baseColor0, hue);\n    vec3 color1 = adjustHue(baseColor1, hue);\n    vec3 color2 = adjustHue(baseColor2, hue);\n    vec3 color3 = adjustHue(baseColor3, hue);\n\n    float len = length(uv);\n    float invLen = len > 0.0 ? 1.0 / len : 0.0;\n\n    float pulse = sin(iTime * 1.1) * 0.045;\n\n    float n0 = snoise3(vec3(uv * noiseScale, iTime * 0.5)) * 0.5 + 0.5;\n\n    float r0 = mix(mix(innerRadius + pulse, 1.0, 0.4), mix(innerRadius + pulse, 1.0, 0.6), n0);\n\n    float d0 = distance(uv, (r0 * invLen) * uv);\n    float v0 = light1(1.0, 10.0, d0);\n    v0 *= smoothstep(r0 * 1.05, r0, len);\n    float cl = cos(atan(uv.y, uv.x) + iTime * 2.0) * 0.5 + 0.5;\n\n    float a = iTime * -1.0;\n    vec2 pos = vec2(cos(a), sin(a)) * r0;\n    float d = distance(uv, pos);\n    float v1 = light2(1.5, 5.0, d);\n    v1 *= light1(1.0, 50.0, d0);\n\n    float v2 = smoothstep(1.0, mix(innerRadius, 1.0, n0 * 0.5), len);\n    float v3 = smoothstep(innerRadius, mix(innerRadius, 1.0, 0.5), len);\n\n    vec3 col = mix(color1, color2, cl);\n    col = mix(col, color0, n0);\n    col = mix(color3, col, v0);\n    col = (col + v1) * v2 * v3;\n    col = clamp(col, 0.0, 1.0);\n\n    return extractAlpha(col);\n  }\n\n  void main() {\n    vec2 center = iResolution.xy * 0.5;\n    float size = min(iResolution.x, iResolution.y);\n    vec2 uv = (vUv * iResolution.xy - center) / size * 2.0;\n\n    float s = sin(rot);\n    float c = cos(rot);\n    uv = vec2(c * uv.x - s * uv.y, s * uv.x + c * uv.y);\n\n    vec4 col = draw(uv);\n    gl_FragColor = vec4(col.rgb * col.a, col.a);\n  }\n";
const gl=canvas.getContext('webgl',{alpha:true,antialias:false,powerPreference:'low-power',premultipliedAlpha:true});
if(gl){
let frame=0,visible=false,paused=false,lost=false,elapsed=0,last=0,lastPaint=0;
function compile(type,source){const shader=gl.createShader(type);gl.shaderSource(shader,source);gl.compileShader(shader);if(!gl.getShaderParameter(shader,gl.COMPILE_STATUS)){gl.deleteShader(shader);throw Error('Orb shader compilation failed')}return shader}
let program,buffer,vs,fs;
try{
vs=compile(gl.VERTEX_SHADER,vertex);fs=compile(gl.FRAGMENT_SHADER,fragment);program=gl.createProgram();gl.attachShader(program,vs);gl.attachShader(program,fs);gl.linkProgram(program);if(!gl.getProgramParameter(program,gl.LINK_STATUS))throw Error('Orb shader link failed');
gl.useProgram(program);buffer=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,buffer);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array([-1,-1,3,-1,-1,3]),gl.STATIC_DRAW);const attr=gl.getAttribLocation(program,'position');gl.enableVertexAttribArray(attr);gl.vertexAttribPointer(attr,2,gl.FLOAT,false,0,0);
const uniforms=Object.fromEntries(['iTime','iResolution','hue','rot','noiseScale','innerRadius'].map(n=>[n,gl.getUniformLocation(program,n)]));
function draw(now){frame=0;if(lost)return;if(last&&visible&&!document.hidden&&!paused&&!reduce.matches)elapsed+=Math.min(now-last,70)*.00028;last=now;
if(now-lastPaint>32||reduce.matches||paused){lastPaint=now;gl.useProgram(program);gl.uniform1f(uniforms.iTime,elapsed);gl.uniform3f(uniforms.iResolution,canvas.width,canvas.height,1);gl.uniform1f(uniforms.hue,0);gl.uniform1f(uniforms.rot,elapsed*.12);gl.uniform1f(uniforms.noiseScale,.65);gl.uniform1f(uniforms.innerRadius,.16);gl.drawArrays(gl.TRIANGLES,0,3)}
if(visible&&!document.hidden&&!paused&&!reduce.matches)frame=requestAnimationFrame(draw)}
function restart(){cancelAnimationFrame(frame);last=0;lastPaint=0;draw(performance.now())}
function resize(){const r=canvas.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,1.5);canvas.width=Math.round(r.width*d);canvas.height=Math.round(r.height*d);gl.viewport(0,0,canvas.width,canvas.height);restart()}
const sizeObserver=new ResizeObserver(resize);sizeObserver.observe(canvas);const observer=new IntersectionObserver(e=>{visible=e[0].isIntersecting;restart()});observer.observe(canvas);
document.addEventListener('visibilitychange',restart);reduce.addEventListener('change',restart);document.addEventListener('ambientmotionchange',e=>{paused=e.detail.paused;restart()});canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();lost=true;cancelAnimationFrame(frame);canvas.parentElement.classList.remove('has-webgl')});
canvas.parentElement.classList.add('has-webgl');resize();
addEventListener('pagehide',()=>{cancelAnimationFrame(frame);sizeObserver.disconnect();observer.disconnect();gl.deleteBuffer(buffer);gl.deleteProgram(program);gl.deleteShader(vs);gl.deleteShader(fs)},{once:true});
}catch(error){canvas.parentElement.classList.remove('has-webgl');console.warn('Static orb fallback active')}
}
// Port of the 21st.dev Glowing Effect: pointer angle + proximity + inactive zone,
// with a restrained blue conic border and no React/Motion runtime dependency.
if(matchMedia('(pointer:fine)').matches){
const surfaces=[...document.querySelectorAll('.glow-surface')];surfaces.forEach(el=>{const edge=document.createElement('span');edge.className='edge-glow';edge.setAttribute('aria-hidden','true');el.append(edge)});
let raf=0;let point={x:-1000,y:-1000};
function update(){raf=0;surfaces.forEach(el=>{const r=el.getBoundingClientRect();if(r.bottom<0||r.top>innerHeight||reduce.matches){el.style.setProperty('--active','0');return}const cx=r.left+r.width*.5,cy=r.top+r.height*.5;const distance=Math.hypot(point.x-cx,point.y-cy);const active=point.x>r.left-40&&point.x<r.right+40&&point.y>r.top-40&&point.y<r.bottom+40&&distance>Math.min(r.width,r.height)*.1;el.style.setProperty('--active',active?'1':'0');if(active)el.style.setProperty('--start',String(180*Math.atan2(point.y-cy,point.x-cx)/Math.PI+90))})}
function schedule(){if(!raf)raf=requestAnimationFrame(update)}document.addEventListener('pointermove',e=>{point={x:e.clientX,y:e.clientY};schedule()},{passive:true});addEventListener('scroll',schedule,{passive:true});reduce.addEventListener('change',schedule);
}
})();
